672	func (e *ManifestRecordError) Error() string {
673		if e.Batch != "" {
674			return fmt.Sprintf("manifest record %d (batch %q): %s", e.Position, e.Batch, e.Reason)
675		}
676		return fmt.Sprintf("manifest record %d: %s", e.Position, e.Reason)
