228	// writeManifest serializes the shared rows as one JSON array file.
229	func writeManifest(t *testing.T, path string, rows []manifestRow) []byte {
230		t.Helper()
231		var buf bytes.Buffer
232		buf.WriteByte('[')
233		for i, r := range rows {
