324		causes := map[saveFault]string{
325			faultWrite:  "injected save failure: new registry content not fully written",
326			faultRename: "injected save failure: complete new registry cannot replace the target",
327		}
328		for _, fault := range []saveFault{faultWrite, faultRename} {
