344					manifestBytes := writeManifest(t, manifest, importFailureManifestRows)
345	
346					code, stdout, stderr := runImportChild(t, registry, manifest, fault, causes[fault], existing)
347	
348					// The caller must observe a command failure, not a success.
349					if code != 1 {
350						t.Fatalf("exit code = %d, want 1; stderr:\n%s", code, stderr)
351					}
352					if len(bytes.TrimSpace(stdout)) != 0 {
