354					}
355					msg := string(stderr)
356					// stderr must identify the command, the target registry path
357					// and the concrete save reason.
358					for _, want := range []string{
359						"govflow: batch-import:",
360						"cannot save registry",
361						registry,
362						causes[fault],
363					} {
