365							t.Fatalf("stderr must contain %q:\n%s", want, msg)
366						}
367					}
368					// The manifest is legal and conflict-free (proven by the
369					// success controls below); the failure wording must never
370					// masquerade as invalid input or a batch conflict.
371					for _, mustNot := range []string{"invalid input", "conflicts with"} {
372						if strings.Contains(msg, mustNot) {
373							t.Fatalf("a save failure must not be reported as %q:\n%s", mustNot, msg)
374						}
375					}
