377					if existing {
378						// The existing registry survives with exact bytes and
379						// modification time and still loads with its original
380						// records, fields and order.
381						info, err := os.Stat(registry)
382						if err != nil {
383							t.Fatalf("the original registry must still exist: %v", err)
384						}
385						if !info.ModTime().Equal(importFailurePinnedModTime) {
386							t.Fatalf("failed import changed the registry mtime: got %v, want %v",
