413						// With no prior registry there must still be no file: not
414						// an empty registry, not the first few manifest rows.
415						if _, err := os.Stat(registry); !os.IsNotExist(err) {
416							t.Fatalf("failed import must not create the registry, stat err=%v", err)
417						}
418					}
419					assertNoSaveLeftovers(t, dir, filepath.Base(manifest), filepath.Base(registry))
