426	// decodeImportEnvelope parses stdout strictly as one JSON object carrying
427	// exactly one member, "results", whose elements are generic objects for
428	// per-key assertions.
429	func decodeImportEnvelope(t *testing.T, raw []byte) []map[string]any {
430		t.Helper()
431		dec := json.NewDecoder(bytes.NewReader(bytes.TrimSpace(raw)))
432		var envelope map[string]json.RawMessage
433		if err := dec.Decode(&envelope); err != nil {
434			t.Fatalf("stdout is not a JSON object: %v (%q)", err, raw)
435		}
436		if err := dec.Decode(&struct{}{}); err != io.EOF {
437			t.Fatalf("stdout must hold exactly one JSON object, got %q", raw)
438		}
439		if len(envelope) != 1 {
440			t.Fatalf("result object must carry exactly \"results\", got keys %v from %q", envelope, raw)
441		}
442		resultsRaw, ok := envelope["results"]
443		if !ok {
444			t.Fatalf("result object is missing \"results\": %q", raw)
445		}
446		var rows []map[string]any
447		if err := json.Unmarshal(resultsRaw, &rows); err != nil {
448			t.Fatalf("results is not an array of objects: %v (%s)", err, resultsRaw)
449		}
450		return rows
451	}
