453	// assertImportResults checks every result entry against its manifest-order
454	// expectation: exactly the five public keys, normalized four fields and the
455	// created/duplicate status.
456	func assertImportResults(t *testing.T, stdout []byte, want []expectedImportRow) {
457		t.Helper()
458		rows := decodeImportEnvelope(t, stdout)
459		if len(rows) != len(want) {
460			t.Fatalf("got %d results, want %d (manifest order): %s", len(rows), len(want), stdout)
461		}
462		for i, w := range want {
463			got := rows[i]
464			if len(got) != 5 {
465				t.Fatalf("result %d carries %d keys, want exactly 5: %v", i+1, len(got), got)
466			}
467			for _, key := range []string{"batch", "product", "quantity", "unit", "status"} {
468				if _, ok := got[key]; !ok {
469					t.Fatalf("result %d is missing key %q: %v", i+1, key, got)
470				}
471			}
472			if got["batch"] != w.batch || got["product"] != w.product || got["unit"] != w.unit {
473				t.Errorf("result %d text fields = %q/%q/%q, want %q/%q/%q",
474					i+1, got["batch"], got["product"], got["unit"], w.batch, w.product, w.unit)
475			}
476			quantity, ok := got["quantity"].(float64)
477			if !ok || int64(quantity) != w.quantity {
478				t.Errorf("result %d quantity = %v, want %d", i+1, got["quantity"], w.quantity)
479			}
480			if got["status"] != w.status {
481				t.Errorf("result %d status = %v, want %q", i+1, got["status"], w.status)
482			}
483		}
484	}
485	
486	// assertResultsMatchRegistry cross-checks every result entry against the
487	// record with the same batch id in the final registry, so completion is
488	// established by field-level content agreement rather than result count.
489	func assertResultsMatchRegistry(t *testing.T, want []expectedImportRow, stored []registerResult) {
490		t.Helper()
491		byID := make(map[string]registerResult, len(stored))
492		for _, b := range stored {
493			byID[b.Batch] = b
494		}
495		for i, r := range want {
496			s, ok := byID[r.batch]
497			if !ok {
498				t.Fatalf("result %d names batch %q which is absent from the final registry", i+1, r.batch)
499			}
500			if s.Product != r.product || s.Quantity != r.quantity || s.Unit != r.unit {
501				t.Fatalf("result %d (%+v) disagrees with the stored record %+v", i+1, r, s)
502			}
503		}
504	}
505	
506	// assertStoredBatches compares the registry's records in file order.
507	func assertStoredBatches(t *testing.T, registry string, want []registerResult) {
508		t.Helper()
509		stored := readStoredBatches(t, registry)
510		if len(stored) != len(want) {
511			t.Fatalf("registry holds %d records, want %d: %+v", len(stored), len(want), stored)
512		}
513		for i, w := range want {
514			got := stored[i]
515			got.Status = ""
516			if got != w {
517				t.Errorf("stored record %d = %+v, want %+v", i+1, got, w)
518			}
519		}
520	}
521	
522	// The success control against an existing registry: with the save healthy the
523	// very manifest that failed above imports. Results arrive in manifest order
524	// with the right statuses and normalized fields, the old records keep their
525	// order and the new batches append in first-occurrence order, and every result
526	// agrees field by field with the final registry.
527	func TestBatchImportCLISaveSuccessAgainstExistingRegistry(t *testing.T) {
528		dir := t.TempDir()
529		registry := filepath.Join(dir, "reg.json")
530		manifest := filepath.Join(dir, "arrivals.json")
531		writeFile(t, registry, importFailureRegistryJSON)
532		if err := os.Chtimes(registry, importFailurePinnedModTime, importFailurePinnedModTime); err != nil {
533			t.Fatal(err)
534		}
535		manifestBytes := writeManifest(t, manifest, importFailureManifestRows)
536	
537		var stdout bytes.Buffer
538		if err := runBatchImport([]string{"--registry", registry, "--input", manifest}, &stdout); err != nil {
539			t.Fatalf("the legal manifest must import when the save does not fail: %v", err)
540		}
541	
542		// A real save must have happened (new batches exist), observable as a new
543		// mtime rather than the pinned one.
544		info, err := os.Stat(registry)
545		if err != nil {
546			t.Fatal(err)
547		}
548		if info.ModTime().Equal(importFailurePinnedModTime) {
549			t.Fatal("a creating import must replace the file; the pinned mtime survived")
550		}
551	
552		assertImportResults(t, stdout.Bytes(), manifestResultsAgainstExisting)
553		stored := readStoredBatches(t, registry)
554		assertStoredBatches(t, registry, storedBatchesAfterExisting)
555		assertResultsMatchRegistry(t, manifestResultsAgainstExisting, stored)
556		assertFileUnchanged(t, manifest, manifestBytes)
557		assertNoSaveLeftovers(t, dir, filepath.Base(manifest), filepath.Base(registry))
558	}
559	
560	// The success control with no prior registry: the file is created, the
561	// formerly-stored batches of the shared manifest are now created too, the
562	// within-manifest repeat is the only duplicate, and results again match the
563	// created file field by field.
564	func TestBatchImportCLISaveSuccessWithMissingRegistry(t *testing.T) {
565		dir := t.TempDir()
566		registry := filepath.Join(dir, "reg.json")
567		manifest := filepath.Join(dir, "arrivals.json")
568		manifestBytes := writeManifest(t, manifest, importFailureManifestRows)
569	
570		var stdout bytes.Buffer
571		if err := runBatchImport([]string{"--registry", registry, "--input", manifest}, &stdout); err != nil {
572			t.Fatalf("the legal manifest must import and create the registry: %v", err)
573		}
574	
575		assertImportResults(t, stdout.Bytes(), manifestResultsWhenMissing)
576		stored := readStoredBatches(t, registry)
577		assertStoredBatches(t, registry, storedBatchesWhenMissing)
578		assertResultsMatchRegistry(t, manifestResultsWhenMissing, stored)
579		assertFileUnchanged(t, manifest, manifestBytes)
580		assertNoSaveLeftovers(t, dir, filepath.Base(manifest), filepath.Base(registry))
581	}
582	
583	// The save-failure path must surface the quoted target path verbatim; this
584	// guards the wording the failure scenarios assert on, in a direct check that
585	// reads naturally when it breaks.
586	func TestBatchImportCLISaveFailureWordingNamesPath(t *testing.T) {
587		dir := t.TempDir()
588		registry := filepath.Join(dir, "reg.json")
589		manifest := filepath.Join(dir, "arrivals.json")
590		writeFile(t, registry, importFailureRegistryJSON)
591		writeManifest(t, manifest, importFailureManifestRows)
592	
593		code, stdout, stderr := runImportChild(t, registry, manifest, faultRename, "injected replacement refusal", true)
594		if code != 1 {
595			t.Fatalf("exit code = %d, want 1; stderr:\n%s", code, stderr)
596		}
597		if len(stdout) != 0 {
598			t.Fatalf("stdout must be empty, got %q", stdout)
599		}
600		want := "cannot save registry " + strconv.Quote(registry) + ": injected replacement refusal"
601		if !strings.Contains(string(stderr), want) {
602			t.Fatalf("stderr must contain %q:\n%s", want, stderr)
603		}
604	}
605

