947	// A registry file whose layout differs from what Save would write — compact,
948	// members in another order — is still not re-saved to confirm a duplicate:
949	// bytes and mtime stay exactly as they were.
950	func TestBatchRegisterCLIDuplicateKeepsForeignFileLayout(t *testing.T) {
951		dir := t.TempDir()
952		registry := filepath.Join(dir, "reg.json")
953		original := `{"batches":[{"unit":"kg","quantity":120,"product":"P-7","batch":"B-001"}],"version":1}`
954		writeFile(t, registry, original)
