969	
970	// Re-registering a batch id with any differing field fails: stdout stays
971	// empty, the error names the batch and every mismatching field — never just
972	// one of several — and the file keeps its bytes and mtime. Interior
973	// whitespace and casing are significant, so "p-7" and "k g" are conflicts,
974	// not duplicates.
975	func TestBatchRegisterCLIConflictReportsAllDifferingFields(t *testing.T) {
976		cases := map[string]struct {
977			product  string
978			quantity string
979			unit     string
980			fields   []string
981		}{
982			"product casing differs":      {"p-7", "120", "kg", []string{"product"}},
983			"unit interior space differs": {"P-7", "120", "k g", []string{"unit"}},
984			"quantity differs":            {"P-7", "121", "kg", []string{"quantity"}},
985			"all three differ":            {"P-8", "121", "g", []string{"product", "quantity", "unit"}},
986		}
987		for name, tc := range cases {
988			t.Run(name, func(t *testing.T) {
989				dir := t.TempDir()
990				registry := filepath.Join(dir, "reg.json")
991				writeFile(t, registry, `{"version":1,"batches":[`+
992					`{"batch":"B-000","product":"P-0","quantity":5,"unit":"box"},`+
993					`{"batch":"B-001","product":"P-7","quantity":120,"unit":"kg"}]}`)
994				content, pinned := pinRegistry(t, registry)
995	
996				stdout, err := registerCLI(t, registry, "B-001", tc.product, tc.quantity, tc.unit)
997				if err == nil {
998					t.Fatal("a conflicting re-registration must fail")
999				}
1000				if stdout != "" {
1001					t.Fatalf("stdout must stay empty on conflict, got %q", stdout)
1002				}
1003				msg := err.Error()
1004				if !strings.Contains(msg, strconv.Quote("B-001")) {
1005					t.Fatalf("error must name the batch: %v", msg)
1006				}
1007				for _, field := range tc.fields {
1008					if !strings.Contains(msg, field) {
1009						t.Fatalf("error must report differing field %q: %v", field, msg)
1010					}
1011				}
1012				assertRegistryUntouched(t, registry, content, pinned)
1013	
1014				batches := readStoredBatches(t, registry)
1015				if len(batches) != 2 || batches[1].Product != "P-7" ||
1016					batches[1].Quantity != 120 || batches[1].Unit != "kg" {
1017					t.Fatalf("the conflict must not overwrite the stored record: %v", batches)
1018				}
1019			})
1020		}
1021	}
