1023	// Batch ids compare byte for byte: "b-001" is a different id from "B-001" and
1024	// registers as its own record, after which it confirms duplicates of its own.
1025	func TestBatchRegisterCLIBatchIDCaseSensitive(t *testing.T) {
1026		dir := t.TempDir()
1027		registry := filepath.Join(dir, "reg.json")
1028	
1029		if _, err := registerCLI(t, registry, "B-001", "P-7", "120", "kg"); err != nil {
1030			t.Fatal(err)
1031		}
1032		stdout, err := registerCLI(t, registry, "b-001", "P-7", "120", "kg")
1033		if err != nil {
1034			t.Fatalf("a case-distinct batch id must register: %v", err)
1035		}
1036		if res := decodeRegisterResult(t, stdout); res.Status != "created" || res.Batch != "b-001" {
