			[]byte("[{\"batch\":\"OK1\",\"product\":\"P\",\"quantity\":1,\"unit\":\"kg\"}," +
				"{\"batch\":\"BAD2\",\"product\":\"P\",\"quantity\":2,\"unit\":\"kg\xff\"}]"),
