140	// abort, clean up its temporary file and leave the existing registry — the
141	// actual replacement target — byte-for-byte and timestamp-for-timestamp
142	// untouched, loading with exactly the original records.
143	func TestSaveWriteFailureKeepsExistingRegistryIntact(t *testing.T) {
144		dir, path, original, originalBytes := setupExistingRegistry(t)
